<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('wallet.view');$id=filter_var(input('id'),FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Not found');}$stmt=db()->prepare('SELECT t.*,u.name,u.mobile,a.name admin_name,r.transaction_id reversal_id FROM wallet_transactions t JOIN users u ON u.id=t.user_id LEFT JOIN admins a ON a.id=t.created_by LEFT JOIN wallet_transactions r ON r.original_transaction_id=t.id WHERE t.id=?');$stmt->execute([$id]);$txn=$stmt->fetch();if(!$txn){http_response_code(404);exit('Not found');}$pageTitle=$txn['transaction_id'];$pageSubtitle='Ledger transaction detail';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Transaction</h2><span class="badge <?=strtolower(e($txn['status']))?>"><?=e($txn['status'])?></span></div><div class="grid detail-grid"><div><div class="kv"><span>User</span><strong><a href="<?=e(app_url('/admin/users/view.php?id='.$txn['user_id']))?>"><?=e($txn['name'])?></a></strong></div><div class="kv"><span>Type</span><strong><?=e($txn['type'])?></strong></div><div class="kv"><span>Amount</span><strong><?=money($txn['amount'])?></strong></div><div class="kv"><span>Balance</span><strong><?=money($txn['previous_balance'])?> → <?=money($txn['new_balance'])?></strong></div></div><div><div class="kv"><span>Reference</span><strong><?=e($txn['reference']??'—')?></strong></div><div class="kv"><span>Description</span><strong><?=e($txn['description']??'—')?></strong></div><div class="kv"><span>Created by</span><strong><?=e($txn['admin_name']??'System/API')?></strong></div><div class="kv"><span>Date</span><strong><?=e($txn['created_at'])?></strong></div></div></div></section>
<?php if(can('wallet.reverse')&&$txn['status']==='SUCCESS'&&$txn['type']!=='REVERSAL'&&!$txn['reversal_id']):?><section class="panel"><h2>Reverse transaction</h2><p class="help">A reversal creates a new ledger entry. It never deletes or rewrites financial history.</p><form method="post" action="<?=e(app_url('/admin/wallets/reverse.php'))?>" class="form-grid" data-confirm="Reverse this transaction? The compensating ledger entry is permanent."><?=csrf_field()?><input type="hidden" name="transaction_id" value="<?=e($txn['id'])?>"><div class="field full"><label>Reason</label><textarea name="reason" maxlength="500" required></textarea></div><div class="field full"><button class="btn danger">Create reversal</button></div></form></section><?php endif?>
